import base64
import os

def initialize_data_directories():
    if not os.path.exists(r"data\builtin"):
        os.makedirs(r"data\builtin")
    if not os.path.exists(r"data\custom"):
        os.makedirs(r"data\custom")

    with open(r"data\builtin\default_seewo_sound.mp3", "wb") as fp:
        fp.write(base64.b64decode(""""""))

    with open(r"data\builtin\default_seewo_image.png", "wb") as fp:
        fp.write(base64.b64decode(""""""))

    with open(r"data\builtin\default_seewo_icon.ico", "wb") as fp:
        fp.write(base64.b64decode(""""""))

if __name__ == "__main__":
    initialize_data_directories()
